import { loadFont as loadPlayfair } from "@remotion/google-fonts/PlayfairDisplay";
import { loadFont as loadCinzel } from "@remotion/google-fonts/Cinzel";
import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, spring, staticFile, useCurrentFrame } from "remotion";

// DAYANE MÍDIAS · recrutamento de revendedoras Made In Brasil Amazon (antiga Amazon SPA), Londrina e região.
// Fala baseada no reel "Seja uma revendedora" + arte "Como funciona" + áudios da Dayane (45 dias, 30%, consignado, acerto do que vendeu).
// v2: voz Roberta com pausas encurtadas (src/voz-v2-curta.wav, 34,5 s). Os tempos abaixo continuam os da v1 (edit/voz-v1.json):
// a tabela NOVA→V1 converte o tempo da voz nova no antigo, palavra por palavra. Layout mais junto e socos de câmera nas palavras-chave.
// Identidade da arte: rosa claro, magenta, vinho, toque dourado; serifada de capa (Playfair), Cinzel na marca, Montserrat no apoio.
// Fotos: páginas do catálogo no Canva (títulos antigos "Amazon SPA" apagados).

const { fontFamily: PF } = loadPlayfair("normal", { weights: ["700", "800", "900"], subsets: ["latin", "latin-ext"] });
const { fontFamily: CZ } = loadCinzel("normal", { weights: ["600", "700"], subsets: ["latin", "latin-ext"] });
const { fontFamily: MS } = loadMontserrat("normal", { weights: ["500", "600", "700", "800"], subsets: ["latin", "latin-ext"] });

export const DY2_FPS = 30;
const LEAD = 0.15;
export const DY2_FRAMES = Math.round(36.2 * DY2_FPS);
const DY_FPS = DY2_FPS;
// voz nova → voz v1 (início de cada palavra)
const NOVA = [0.0, 0.18, 0.9, 1.12, 1.52, 1.68, 1.8, 1.98, 2.34, 2.66, 2.84, 3.2, 3.5, 3.68, 3.84, 4.4, 4.8, 4.94, 5.7, 6.08, 6.2, 6.58, 7.36, 7.64, 8.1, 8.2, 8.46, 9.0, 9.24, 9.78, 9.96, 11.12, 11.3, 11.5, 12.1, 12.36, 12.96, 13.8, 14.18, 14.5, 14.78, 14.94, 15.26, 15.56, 16.2, 17.06, 17.38, 17.74, 18.14, 18.52, 18.8, 19.3, 19.62, 19.78, 20.2, 20.58, 20.7, 21.08, 21.52, 21.66, 22.14, 22.46, 22.6, 22.74, 23.5, 23.88, 24.18, 24.36, 24.88, 25.04, 25.78, 26.08, 26.34, 27.02, 27.38, 27.8, 28.04, 28.52, 28.9, 29.06, 29.56, 29.68, 30.3, 30.54, 30.88, 31.28, 31.5, 32.28, 32.74, 32.84, 33.26, 33.46, 33.82, 34.0];
const V1 = [0.0, 0.18, 0.82, 1.12, 1.46, 1.56, 1.66, 1.78, 2.08, 2.42, 2.76, 3.04, 3.38, 3.58, 3.72, 4.48, 5.16, 5.26, 5.84, 6.22, 6.32, 6.7, 7.66, 8.26, 8.62, 8.74, 8.98, 9.46, 9.66, 10.14, 10.34, 11.12, 11.86, 12.06, 12.68, 13.46, 14.3, 15.1, 15.78, 16.08, 16.34, 16.46, 16.72, 16.92, 17.5, 18.46, 18.84, 19.12, 19.48, 19.82, 20.1, 20.52, 20.76, 20.9, 21.36, 21.9, 22.02, 22.36, 22.8, 22.9, 23.4, 23.88, 24.02, 24.14, 25.02, 25.58, 25.76, 25.92, 26.46, 26.6, 27.44, 27.8, 28.08, 28.78, 29.32, 29.86, 30.06, 30.92, 31.54, 31.7, 32.26, 32.62, 33.48, 34.02, 34.3, 34.7, 34.9, 35.72, 36.18, 36.3, 36.66, 37.02, 37.3, 37.48];
const toV1 = (x: number) => x <= NOVA[0] ? x : x >= NOVA[NOVA.length - 1] ? V1[V1.length - 1] + (x - NOVA[NOVA.length - 1]) : interpolate(x, NOVA, V1);

const BLUSH = "#FCE6EE";
const PINK = "#F6C9D8";
const MAG = "#E2185B";
const WINE = "#7A0E32";
const GOLD = "#D4A23C";
const WHITE = "#FFFFFF";
const GRAY = "#6E4A57";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const k = (t: number, a: number, d: number) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const sp = (t: number, a: number, damping = 14, stiffness = 180) =>
  spring({ frame: Math.round((t - a) * DY_FPS), fps: DY_FPS, config: { damping, stiffness } });
const img = (f: string) => staticFile(`dayane/${f}`);

// ───────── texto ─────────
type W = [string, number];
const Words: React.FC<{ t: number; words: W[]; size?: number; color?: string; font?: string; weight?: number }> = ({ t, words, size = 58, color = WINE, font = MS, weight = 600 }) => (
  <div style={{ fontFamily: font, fontWeight: weight, fontSize: size, lineHeight: 1.2, color, textAlign: "center", whiteSpace: "nowrap" }}>
    {words.map(([w, at], i) => {
      const q = k(t, at, 0.2);
      return <span key={i} style={{ display: "inline-block", margin: "0 0.13em", opacity: Math.min(1, q * 2), transform: `translateY(${(1 - q) * 46}px) scale(${0.55 + 0.45 * q})` }}>{w}</span>;
    })}
  </div>
);
const Title: React.FC<{ t: number; at: number; children: React.ReactNode; size?: number; color?: string; italic?: boolean }> = ({ t, at, children, size = 120, color = MAG, italic }) => {
  const s = sp(t, at, 10, 260);
  return (
    <div style={{ fontFamily: PF, fontWeight: 800, fontStyle: italic ? "italic" : "normal", fontSize: size, lineHeight: 1.02, letterSpacing: "-0.01em", textAlign: "center", whiteSpace: "nowrap", color,
      opacity: Math.min(1, s * 3), transform: `scale(${1.7 - 0.7 * s})` }}>{children}</div>
  );
};
// fio dourado que se desenha (o detalhe dourado da arte)
const GoldLine: React.FC<{ t: number; at: number; w?: number }> = ({ t, at, w = 360 }) => {
  const q = k(t, at, 0.6);
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 18, opacity: q }}>
      <div style={{ width: (w / 2) * q, height: 4, borderRadius: 2, background: GOLD }} />
      <div style={{ width: 16, height: 16, background: GOLD, transform: `rotate(45deg) scale(${q})` }} />
      <div style={{ width: (w / 2) * q, height: 4, borderRadius: 2, background: GOLD }} />
    </div>
  );
};

// ───────── cena e transições ─────────
type Tr = "none" | "slideL" | "slideUp" | "circle" | "wipe" | "zoom" | "iris" | "band";
const TD = 0.3;
const Scene: React.FC<{ t: number; a: number; b: number; tr: Tr; bg: string; cam?: [number, number]; drift?: number; hits?: number[]; children: React.ReactNode }> = ({ t, a, b, tr, bg, cam = [1, 1.06], drift = -30, hits = [], children }) => {
  if (t < a || t > b + TD) return null;
  const q = tr === "none" ? 1 : k(t, a, TD);
  let clip = "none", tf = "", op = 1;
  if (tr === "band") clip = `polygon(0 ${(1 - q) * 100}%, 100% ${(1 - q) * 100 - 20 * (1 - q)}%, 100% 100%, 0 100%)`;
  if (tr === "wipe") clip = `polygon(0 0, ${q * 125}% 0, ${q * 125 - 25}% 100%, 0 100%)`;
  if (tr === "slideL") tf = `translateX(${(1 - q) * 100}%)`;
  if (tr === "slideUp") tf = `translateY(${(1 - q) * 100}%)`;
  if (tr === "zoom") { tf = `scale(${1.3 - 0.3 * q})`; op = Math.min(1, q * 1.7); }
  if (tr === "circle") clip = `circle(${q * 120}% at 50% 50%)`;
  if (tr === "iris") clip = `inset(${(1 - q) * 50}% ${(1 - q) * 50}% round ${(1 - q) * 200}px)`;
  const p = lin(t, a, b + TD);
  // soco de câmera: entra 8% maior e assenta; cada palavra-chave dá um soco curto
  const punch = 0.08 * (1 - k(t, a, 0.45)) + hits.reduce((m, h) => m + (t >= h ? 0.045 * Math.exp(-(t - h) * 9) : 0), 0);
  const z = Math.max(cam[0] + (cam[1] - cam[0]) * p, 1.006 + (Math.abs(drift * p) * 2) / 1920) + punch;
  return (
    <AbsoluteFill style={{ clipPath: clip, transform: tf || undefined, opacity: op, overflow: "hidden", background: bg }}>
      <AbsoluteFill style={{ transform: `translateY(${(drift * p).toFixed(1)}px) scale(${z.toFixed(4)})` }}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};

// ───────── peças ─────────
// selo da marca (tinta do logo recortada; cor livre)
const Seal: React.FC<{ size: number; color?: string }> = ({ size, color = MAG }) => (
  <div style={{ width: size, height: size * (594 / 606), background: color, WebkitMaskImage: `url(${img("logo-mask.png")})`, WebkitMaskSize: "100% 100%", maskImage: `url(${img("logo-mask.png")})`, maskSize: "100% 100%" }} />
);

const Icon: React.FC<{ kind: "money" | "cal" | "pin" | "phone" | "team" | "mega" | "gift" | "check"; size: number; bg?: string; fg?: string }> = ({ kind, size, bg = MAG, fg = WHITE }) => (
  <svg width={size} height={size} viewBox="0 0 100 100" style={{ flex: "none" }}>
    <circle cx={50} cy={50} r={49} fill={bg} />
    {kind === "money" && <text x={50} y={69} textAnchor="middle" fontFamily={MS} fontWeight={800} fontSize={56} fill={fg}>$</text>}
    {kind === "cal" && (<g fill="none" stroke={fg} strokeWidth={6} strokeLinecap="round" strokeLinejoin="round"><rect x={26} y={30} width={48} height={44} rx={7} /><line x1={26} y1={44} x2={74} y2={44} /><line x1={38} y1={23} x2={38} y2={34} /><line x1={62} y1={23} x2={62} y2={34} /></g>)}
    {kind === "pin" && (<g><path d="M50 22 C36 22 28 32 28 44 C28 60 50 80 50 80 C50 80 72 60 72 44 C72 32 64 22 50 22 Z" fill={fg} /><circle cx={50} cy={44} r={9} fill={bg} /></g>)}
    {kind === "phone" && <path d="M36 25 l9 0 l5 14 l-7 5 c3 7 8 12 15 15 l5 -7 l14 5 l0 9 c0 5 -4 9 -9 8 c-22 -3 -38 -19 -41 -41 c-1 -5 3 -8 9 -8 z" fill={fg} />}
    {kind === "team" && (<g fill={fg}><circle cx={38} cy={40} r={9} /><circle cx={62} cy={40} r={9} /><path d="M22 72 c0 -12 7 -19 16 -19 s16 7 16 19 z" /><path d="M46 72 c0 -12 7 -19 16 -19 s16 7 16 19 z" /></g>)}
    {kind === "mega" && (<g fill={fg}><path d="M26 44 l14 0 l26 -14 l0 40 l-26 -14 l-14 0 z" /><rect x={34} y={58} width={9} height={14} rx={3} /><path d="M72 42 q6 8 0 16" stroke={fg} strokeWidth={5} fill="none" strokeLinecap="round" /></g>)}
    {kind === "gift" && (<g fill={fg}><rect x={26} y={44} width={48} height={30} rx={4} /><rect x={22} y={34} width={56} height={12} rx={4} /><rect x={46} y={34} width={8} height={40} fill={bg} /><path d="M50 34 c-6 -10 -18 -10 -16 -2 c1 3 8 3 16 2 z M50 34 c6 -10 18 -10 16 -2 c-1 3 -8 3 -16 2 z" /></g>)}
    {kind === "check" && <path d="M28 52 L44 67 L73 35" fill="none" stroke={fg} strokeWidth={11} strokeLinecap="round" strokeLinejoin="round" />}
  </svg>
);

const Pop: React.FC<{ t: number; at: number; children: React.ReactNode; rot?: number }> = ({ t, at, children, rot = 0 }) => {
  const s = sp(t, at, 11, 230);
  return <div style={{ opacity: Math.min(1, s * 3), transform: `scale(${0.3 + 0.7 * s}) rotate(${(1 - s) * -18 + rot}deg)` }}>{children}</div>;
};

const Pill: React.FC<{ t: number; at: number; children: React.ReactNode; bg?: string; color?: string; size?: number }> = ({ t, at, children, bg = MAG, color = WHITE, size = 56 }) => {
  const s = sp(t, at, 13, 210);
  return (
    <div style={{ padding: "20px 52px 24px", borderRadius: 70, background: bg, color, fontFamily: MS, fontWeight: 800, fontSize: size, whiteSpace: "nowrap", boxShadow: "0 24px 60px rgba(122,14,50,0.25)",
      opacity: Math.min(1, s * 3), transform: `scale(${0.4 + 0.6 * s})` }}>{children}</div>
  );
};

const Perk: React.FC<{ t: number; at: number; icon: "team" | "mega" | "gift"; title: string }> = ({ t, at, icon, title }) => {
  const s = sp(t, at, 14, 200);
  return (
    <div style={{ width: 840, display: "flex", alignItems: "center", gap: 34, padding: "44px 44px", borderRadius: 44, background: WHITE, boxShadow: "0 24px 60px rgba(122,14,50,0.14)", boxSizing: "border-box",
      opacity: Math.min(1, s * 3), transform: `translateX(${(1 - s) * 500}px) rotate(${(1 - s) * 6}deg)` }}>
      <Pop t={t} at={at + 0.1}><Icon kind={icon} size={124} /></Pop>
      <div style={{ fontFamily: PF, fontWeight: 800, fontSize: 56, lineHeight: 1.05, color: WINE, whiteSpace: "nowrap" }}>{title}</div>
    </div>
  );
};

// coluna central: tudo da cena num bloco só, centralizado na altura, sem buraco entre texto e peça
const Stack: React.FC<{ t: number; at?: number; out?: number; gap?: number; dy?: number; children: React.ReactNode }> = ({ t, at = -99, out, gap = 34, dy = 0, children }) => {
  if (t < at - 0.05 || (out !== undefined && t > out + 0.14)) return null;
  const o = out === undefined ? 0 : k(t, out, 0.12);
  return (
    <div style={{ position: "absolute", left: 120, right: 120, top: dy, bottom: -dy, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap,
      opacity: 1 - o, transform: `scale(${1 - o * 0.08})` }}>{children}</div>
  );
};
// foto em fluxo (dentro da coluna)
const Foto: React.FC<{ t: number; at: number; src: string; w: number; h: number; rot?: number; from?: "down" | "big" | "left" | "right"; pos?: string; z?: [number, number]; dur?: number }> = ({ t, at, src, w, h, rot = 0, from = "big", pos = "50% 50%", z = [1.16, 1.0], dur = 3 }) => {
  const s = sp(t, at, 13, 200);
  const e = lin(t, at, at + dur);
  const enter = from === "big" ? `scale(${1.5 - 0.5 * s})` : from === "down" ? `translateY(${(1 - s) * 1200}px) rotate(${(1 - s) * 12}deg)` : `translateX(${(1 - s) * (from === "left" ? -1100 : 1100)}px) rotate(${(1 - s) * (from === "left" ? -12 : 12)}deg)`;
  return (
    <div style={{ width: w, height: h, flex: "none", borderRadius: 40, overflow: "hidden", background: WHITE, border: `12px solid ${WHITE}`, boxShadow: "0 40px 90px rgba(122,14,50,0.28)",
      opacity: Math.min(1, s * 3), transform: `${enter} rotate(${rot}deg)` }}>
      <Img src={img(src)} style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: pos, borderRadius: 30, transform: `scale(${z[0] + (z[1] - z[0]) * e})` }} />
    </div>
  );
};

// ───────── composição ─────────
export const DayaneV2: React.FC = () => {
  const frame = useCurrentFrame();
  const t = toV1(frame / DY_FPS - LEAD);
  return (
    <AbsoluteFill style={{ background: BLUSH, overflow: "hidden" }}>
      {/* 1 · E você, já pensou em ter uma renda extra que pode mudar a sua vida? */}
      <Scene t={t} a={-0.2} b={4.38} tr="none" bg={BLUSH} cam={[1.12, 1.0]} drift={0} hits={[1.78, 3.38]}>
        {(() => {
          const r = k(t, -0.1, 0.6);
          return <div style={{ position: "absolute", left: 540 - 600, top: 960 - 600, width: 1200, height: 1200, borderRadius: 600, border: `${70 * (1 - r) + 4}px solid ${MAG}`, opacity: 1 - r, transform: `scale(${0.15 + 0.85 * r})` }} />;
        })()}
        <Stack t={t} out={0.95}>
          <Title t={t} at={-0.05} size={230} italic>E você?</Title>
        </Stack>
        <Stack t={t} at={1.0} out={2.95} gap={24}>
          <Pop t={t} at={1.0}><Icon kind="money" size={240} /></Pop>
          <Words t={t} size={74} words={[["já", 1.05], ["pensou", 1.12], ["em", 1.46], ["ter", 1.56], ["uma", 1.66]]} />
          <Title t={t} at={1.78} size={172}>renda extra?</Title>
        </Stack>
        <Stack t={t} at={3.0} gap={18}>
          <Words t={t} size={74} words={[["que", 3.0], ["pode", 3.0], ["mudar", 3.04]]} />
          <Title t={t} at={3.38} size={180} italic>a sua vida?</Title>
          <GoldLine t={t} at={3.6} w={460} />
        </Stack>
      </Scene>

      {/* 2 · Seja uma revendedora Made in Brasil Amazon */}
      <Scene t={t} a={4.38} b={7.6} tr="circle" bg={MAG} cam={[1.0, 1.06]} drift={-20} hits={[5.26, 5.84]}>
        <Stack t={t} gap={40}>
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
            <Words t={t} size={74} color={WHITE} words={[["Seja", 4.48], ["uma", 5.1]]} />
            <Title t={t} at={5.26} size={150} color={WHITE}>revendedora</Title>
          </div>
          {(() => {
            const s = sp(t, 5.84, 11, 200);
            return <div style={{ opacity: Math.min(1, s * 3), transform: `scale(${0.3 + 0.7 * s}) rotate(${(1 - s) * -24}deg)` }}><Seal size={640} color={WHITE} /></div>;
          })()}
        </Stack>
      </Scene>

      {/* 3 · kit completo de produtos em consignação, pronto pra vender */}
      <Scene t={t} a={7.6} b={12.62} tr="slideL" bg={BLUSH} cam={[1.0, 1.06]} drift={-24} hits={[8.74, 10.3, 11.12]}>
        <Stack t={t} gap={44}>
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 4 }}>
            <Words t={t} size={66} words={[["Você", 7.7], ["recebe", 8.26], ["um", 8.62]]} />
            <Title t={t} at={8.74} size={140}>kit completo</Title>
          </div>
          <div style={{ display: "flex", gap: 0, justifyContent: "center", width: 840 }}>
            <Foto t={t} at={8.85} src="kit-desmaia.jpg" w={450} h={680} rot={-5} from="left" pos="50% 60%" dur={4} />
            <div style={{ marginLeft: -60, marginTop: 50 }}><Foto t={t} at={9.62} src="kit-blond.jpg" w={450} h={680} rot={5} from="right" pos="50% 60%" dur={4} /></div>
          </div>
          <div style={{ position: "relative", height: 112, width: 840 }}>
            <Stack t={t} at={10.3} out={11.0} gap={0}><Pill t={t} at={10.3} size={66}>em consignação</Pill></Stack>
            <Stack t={t} at={11.12} gap={0}><Pill t={t} at={11.12} bg={WINE} size={66}>pronto pra vender</Pill></Stack>
          </div>
        </Stack>
      </Scene>

      {/* 4 · sem investimento inicial */}
      <Scene t={t} a={12.62} b={15.1} tr="zoom" bg={WINE} cam={[1.08, 1.0]} drift={0} hits={[12.68, 13.46, 14.3]}>
        <Stack t={t} gap={30}>
          {(() => {
            const s = sp(t, 12.68, 9, 260);
            return (
              <div style={{ opacity: Math.min(1, s * 3), transform: `scale(${2.4 - 1.4 * s}) rotate(${-6 + (1 - s) * -12}deg)`, marginBottom: 30 }}>
                <div style={{ fontFamily: PF, fontWeight: 900, fontSize: 230, color: WHITE, border: `14px solid ${WHITE}`, borderRadius: 40, padding: "0 70px 24px", lineHeight: 1.1 }}>Sem</div>
              </div>
            );
          })()}
          <Title t={t} at={13.46} size={136} color={PINK}>investimento</Title>
          <Title t={t} at={14.3} size={150} color={WHITE} italic>inicial</Title>
          <GoldLine t={t} at={14.4} w={460} />
        </Stack>
      </Scene>

      {/* 5 · o kit fica com você por 45 dias */}
      <Scene t={t} a={15.1} b={18.3} tr="wipe" bg={BLUSH} cam={[1.0, 1.07]} drift={-24} hits={[16.92, 17.5]}>
        <Stack t={t} gap={20}>
          <Words t={t} size={74} words={[["O", 15.35], ["kit", 15.78], ["fica", 16.08], ["com", 16.34], ["você", 16.46]]} />
          {(() => {
            const s = sp(t, 16.72, 10, 240);
            const n = Math.round(45 * k(t, 16.85, 0.6));
            return (
              <div style={{ display: "flex", alignItems: "center", gap: 30, opacity: Math.min(1, s * 3), transform: `scale(${0.4 + 0.6 * s})` }}>
                <Pop t={t} at={16.75}><Icon kind="cal" size={210} /></Pop>
                <div style={{ fontFamily: PF, fontWeight: 900, fontSize: 380, lineHeight: 1, color: MAG, fontVariantNumeric: "tabular-nums" }}>{n}</div>
              </div>
            );
          })()}
          <div style={{ marginTop: 40 }}><Title t={t} at={17.5} size={150} color={WINE}>dias</Title></div>
        </Stack>
      </Scene>

      {/* 6 · 30% de comissão sobre as vendas */}
      <Scene t={t} a={18.3} b={21.3} tr="iris" bg={MAG} cam={[1.08, 1.0]} drift={0} hits={[19.12, 20.1]}>
        <Stack t={t} gap={40}>
          <Words t={t} size={74} color={WHITE} words={[["você", 18.46], ["ganha", 18.84]]} />
          {(() => {
            const s = sp(t, 19.1, 10, 240);
            const n = Math.round(30 * k(t, 19.12, 0.5));
            return (
              <div style={{ width: 800, padding: "50px 0 60px", borderRadius: 60, background: WHITE, boxShadow: "0 40px 90px rgba(80,0,30,0.35)",
                display: "flex", flexDirection: "column", alignItems: "center", gap: 10, opacity: Math.min(1, s * 3), transform: `scale(${0.4 + 0.6 * s}) rotate(${(1 - s) * 10}deg)` }}>
                <div style={{ fontFamily: PF, fontWeight: 900, fontSize: 320, lineHeight: 1, color: MAG, fontVariantNumeric: "tabular-nums" }}>{n}%</div>
                <div style={{ marginTop: 30, fontFamily: CZ, fontWeight: 700, fontSize: 68, letterSpacing: "0.06em", color: WINE, opacity: k(t, 20.1, 0.25) }}>DE COMISSÃO</div>
              </div>
            );
          })()}
          <Words t={t} size={70} color={WHITE} words={[["sobre", 20.52], ["as", 20.76], ["vendas", 20.9]]} />
        </Stack>
      </Scene>

      {/* 7 · e no final faz o acerto só do que vendeu */}
